mapper.select:
SELECT COUNT(1)
FROM exp_account
WHERE account_name = #{accountName}

    AND account_id != #{excludeAccountId}

SELECT ra.principal_id as accountId, r.role_id as roleId, r.role_name as roleName FROM exp_role_assign ra INNER JOIN exp_role r ON ra.role_id = r.role_id WHERE ra.principal_type = 'ACCOUNT' AND ra.status = 'ENABLED' AND ra.principal_id IN
#{accountId}
ORDER BY ra.principal_id, r.sort_no
